#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Point {
    int x, y;
    Point(int x = 0, int y = 0) : x(x), y(y) {}
};

Point minPoint(Point a, Point b) {
    if (a.x == b.x) return a.y < b.y ? a : b;
    return a.x < b.x ? a : b;
}

Point sumPoint(Point a, Point b) {
    return Point(a.x + b.x, a.y + b.y);
}

int hashPoint(int x, int y, int p, int N) {
    return x * N * 3 + y * 3 + p;
}

bool inBoard(int x, int y, int N) {
    return x >= 0 && x < N && y >= 0 && y < N;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = N * N * 3;
    vector<Point> pos(N * N);
    vector<vector<int>> A(N, vector<int>(N));
    for (int x = 0; x < N; x++) {
        for (int y = 0; y < N; y++) {
            cin >> A[x][y];
            A[x][y]--;
            pos[A[x][y]] = Point(x, y);
        }
    }

    vector<vector<Point>> dist(M, vector<Point>(M, Point(INF, INF)));
    for (int i = 0; i < M; i++) {
        dist[i][i] = Point(0, 0);
    }

    const int knightDx[8] = {2, -2, 2, -2, 1, -1, 1, -1};
    const int knightDy[8] = {1, 1, -1, -1, 2, 2, -2, -2};

    for (int x = 0; x < N; x++) {
        for (int y = 0; y < N; y++) {
            // Knight
            for (int d = 0; d < 8; d++) {
                int nx = x + knightDx[d];
                int ny = y + knightDy[d];
                if (inBoard(nx, ny, N)) {
                    int u = hashPoint(x, y, 0, N);
                    int v = hashPoint(nx, ny, 0, N);
                    dist[u][v] = Point(1, 0);
                }
            }
            // Bishop
            for (int i = -N + 1; i <= N - 1; i++) {
                int nx = x + i;
                int ny = y + i;
                if (inBoard(nx, ny, N)) {
                    int u = hashPoint(x, y, 1, N);
                    int v = hashPoint(nx, ny, 1, N);
                    dist[u][v] = Point(1, 0);
                }
                ny = y - i;
                if (inBoard(nx, ny, N)) {
                    int u = hashPoint(x, y, 1, N);
                    int v = hashPoint(nx, ny, 1, N);
                    dist[u][v] = Point(1, 0);
                }
            }
            // Rook
            for (int i = 0; i < N; i++) {
                int nx = i;
                int ny = y;
                int u = hashPoint(x, y, 2, N);
                int v = hashPoint(nx, ny, 2, N);
                dist[u][v] = Point(1, 0);

                nx = x;
                ny = i;
                u = hashPoint(x, y, 2, N);
                v = hashPoint(nx, ny, 2, N);
                dist[u][v] = Point(1, 0);
            }
            // Piece changes
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i != j) {
                        int u = hashPoint(x, y, i, N);
                        int v = hashPoint(x, y, j, N);
                        dist[u][v] = Point(1, 1);
                    }
                }
            }
        }
    }

    // Floyd-Warshall
    for (int k = 0; k < M; k++) {
        for (int i = 0; i < M; i++) {
            if (dist[i][k].x == INF) continue;
            for (int j = 0; j < M; j++) {
                if (dist[k][j].x == INF) continue;
                Point cand = sumPoint(dist[i][k], dist[k][j]);
                if (cand.x < dist[i][j].x || (cand.x == dist[i][j].x && cand.y < dist[i][j].y)) {
                    dist[i][j] = cand;
                }
            }
        }
    }

    int total = N * N;
    vector<array<Point, 3>> dp(total);
    for (int i = 0; i < total; i++) {
        for (int j = 0; j < 3; j++) {
            dp[i][j] = Point(INF, INF);
        }
    }
